const game=new GF.Game({id:'harbor-courier',title:'Harbor Courier',width:960,height:540,palette:['#1679A8','#F8D66D','#F47B62','#F5F1DF','#247B5A'],background:'#1679A8',seed:314159});
const C={water:'#1679A8',foam:'#8ed9df',sand:'#F8D66D',road:'#f5f1df',line:'#d5cdb7',coral:'#F47B62',green:'#247B5A',ink:'#17445a',cream:'#fff9e8'};
const emit=(type,data)=>{if(typeof game.event==='function')game.event(type,data);else{const g=window.__GF__;if(g){g.events=g.events||[];if(g.events.length<80)g.events.push({type,data});}window.dispatchEvent(new CustomEvent('gf-event',{detail:{type,data}}));}};
const scene={
 init(){this.buildings=[{x:275,y:132,w:170,h:105,c:'#F47B62',n:'Coral apartments'},{x:510,y:185,w:155,h:135,c:'#F8D66D',n:'Sunny hotel'},{x:705,y:245,w:115,h:105,c:'#247B5A',n:'Harbor hall'},{x:290,y:368,w:175,h:75,c:'#f09b76',n:'Bakery'},{x:55,y:70,w:130,h:105,c:'#f2c768',n:'Post office'}];this.planters=[{x:185,y:242,w:82,h:32},{x:455,y:334,w:112,h:32},{x:676,y:80,w:84,h:30},{x:810,y:130,w:33,h:82}];this.orders=[{depot:[162,286],dest:[372,286],name:'Lighthouse Café',color:'#F8D66D'},{depot:[434,105],dest:[720,112],name:'Coral House',color:'#F47B62'},{depot:[648,420],dest:[850,397],name:'Marina Market',color:'#247B5A'}];},
 reset(){this.x=145;this.y=286;this.vx=0;this.vy=0;this.order=0;this.carry=false;this.timer=90;this.moved=0;this.driveSent=false;this.bump=0;this.warn=false;this.rings=[];this.dust=0;this.runCount=(this.runCount||0)+1;if(this.runCount>1)emit('fresh_run_started',{run:this.runCount});},
 solid(x,y){if(x<28||x>932||y<70||y>510)return 'water edge';for(const b of this.buildings)if(x>b.x-11&&x<b.x+b.w+11&&y>b.y-11&&y<b.y+b.h+11)return 'building';for(const p of this.planters)if(x>p.x-10&&x<p.x+p.w+10&&y>p.y-10&&y<p.y+p.h+10)return 'planter';return '';},
 bumpInto(kind){if(this.bump<=0){this.bump=.2;game.shake(3,.18);GF.Sfx.noise({dur:.055,vol:.13,freq:700});emit('obstacle_collision_blocked',{kind});}},
 pickup(){this.carry=true;const o=this.orders[this.order];game.burst(this.x,this.y,{count:14,speed:95,size:3,life:.55,colors:[C.cream,C.sand,'#F47B62'],gravity:100});GF.Sfx.beep({freq:540,to:760,dur:.12,type:'triangle',vol:.24});},
 deliver(){const o=this.orders[this.order],before=game.score,bonus=Math.max(0,Math.floor(this.timer));const gained=100+bonus;game.addScore(gained);emit('score_change',{before,after:game.score,delivery:o.name});this.timer=Math.min(99,this.timer+3);this.carry=false;this.order++;game.hitStop(.08);game.shake(4,.18);game.flash('#fff2c4',.35);game.burst(this.x,this.y,{count:32,speed:180,size:4,life:.9,colors:[o.color,C.sand,C.cream,'#F47B62'],gravity:180});this.rings.push({x:this.x,y:this.y,r:12,life:1,color:o.color});GF.Sfx.melody([[784,.08],[988,.09],[1175,.16]],{type:'triangle',vol:.25});if(!this.driveSent&&this.moved>18){this.driveSent=true;emit('courier_drive_confirmed',{distance:Math.round(this.moved),score:game.score});}if(this.order>=3){emit('delivery_sequence_completed',{destinations:['Lighthouse Café','Coral House','Marina Market'],delivered:3});game.win({message:'ALL DOORSTEPS RUNG!'});}},
 update(dt){if(game.input.keys.Escape){game.state='title';return;}this.timer-=dt;this.bump=Math.max(0,this.bump-dt);if(this.timer<=10&&!this.warn){this.warn=true;game.flash('#F47B62',.22);GF.Sfx.beep({freq:660,dur:.08,type:'square',vol:.18});}if(this.timer<=0){this.timer=0;game.gameOver({message:'SHIFT TIME RAN OUT'});return;}let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0),iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);let active=this.orders[Math.min(this.order,2)];let pt=this.carry?active.dest:active.depot;let dx=pt[0]-this.x,dy=pt[1]-this.y,dl=Math.hypot(dx,dy)||1;if(ix||iy){let il=Math.hypot(ix,iy)||1;ix/=il;iy/=il;ix=ix*.55+dx/dl*.45;iy=iy*.55+dy/dl*.45;}let mag=Math.hypot(ix,iy);if(mag>0){ix/=mag;iy/=mag;this.vx+=ix*430*dt;this.vy+=iy*430*dt;}else{this.vx*=Math.max(0,1-5*dt);this.vy*=Math.max(0,1-5*dt);}let sp=Math.hypot(this.vx,this.vy),max=190;if(sp>max){this.vx=this.vx/sp*max;this.vy=this.vy/sp*max;}let nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;let k=this.solid(nx,this.y);if(k){this.vx=0;this.bumpInto(k);}else this.x=nx;k=this.solid(this.x,ny);if(k){this.vy=0;this.bumpInto(k);}else this.y=ny;if(mag>0){this.moved+=sp*dt;this.dust-=dt;if(this.dust<=0){this.dust=.16;game.burst(this.x-8,this.y+8,{count:1,speed:20,size:2,life:.4,colors:['#d8cba8'],gravity:0});}}let near=Math.hypot(this.x-pt[0],this.y-pt[1]);if(near<37){if(this.carry)this.deliver();else this.pickup();}for(let i=this.rings.length-1;i>=0;i--){let r=this.rings[i];r.life-=dt;r.r+=70*dt;if(r.life<=0)this.rings.splice(i,1);}},
 marker(ctx,p,color,label,parcel){let pulse=1+Math.sin(game.time*5)*.08;ctx.save();ctx.globalAlpha=.19;ctx.fillStyle=color;ctx.beginPath();ctx.arc(p[0],p[1],37*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(p[0],p[1],25,0,Math.PI*2);ctx.stroke();ctx.fillStyle=C.cream;ctx.beginPath();ctx.arc(p[0],p[1],16,0,Math.PI*2);ctx.fill();if(parcel){ctx.fillStyle=color;ctx.fillRect(p[0]-8,p[1]-6,16,12);ctx.strokeStyle=C.ink;ctx.lineWidth=1;ctx.strokeRect(p[0]-8,p[1]-6,16,12);ctx.beginPath();ctx.moveTo(p[0],p[1]-6);ctx.lineTo(p[0],p[1]+6);ctx.stroke();}else GF.Draw.text(ctx,'⌂',p[0],p[1]+1,{size:20,color,weight:'900'});GF.Draw.text(ctx,label,p[0],p[1]-45,{size:14,color:C.ink,weight:'900'});ctx.restore();},
 draw(ctx){let g=ctx.createLinearGradient(0,0,960,540);g.addColorStop(0,'#46b8c5');g.addColorStop(1,C.water);ctx.fillStyle=g;ctx.fillRect(0,0,960,540);ctx.strokeStyle='rgba(245,241,223,.48)';ctx.lineWidth=2;for(let y=82;y<535;y+=31)for(let x=(y%62);x<960;x+=86){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+19,y);ctx.stroke();}ctx.fillStyle=C.sand;ctx.fillRect(25,57,910,455);ctx.fillStyle=C.road;ctx.fillRect(35,190,890,110);ctx.fillRect(205,70,78,430);ctx.fillRect(430,70,78,430);ctx.fillRect(650,70,70,430);ctx.fillRect(810,70,82,430);ctx.strokeStyle=C.line;ctx.lineWidth=3;ctx.setLineDash([12,12]);for(let x=60;x<910;x+=1){ctx.beginPath();ctx.moveTo(x,245);ctx.lineTo(x+1,245);ctx.stroke();}ctx.setLineDash([]);for(const b of this.buildings){GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,13,'rgba(23,68,90,.18)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.c);ctx.fillStyle='rgba(255,249,232,.7)';for(let wx=b.x+17;wx<b.x+b.w-12;wx+=30)ctx.fillRect(wx,b.y+22,13,18);GF.Draw.text(ctx,b.n,b.x+b.w/2,b.y+b.h-13,{size:11,color:C.ink,weight:'800'});}for(const p of this.planters){GF.Draw.roundRect(ctx,p.x,p.y,p.w,p.h,12,'#d98b57');GF.Draw.roundRect(ctx,p.x+5,p.y+5,p.w-10,p.h-10,10,C.green);}ctx.strokeStyle='#835f47';ctx.lineWidth=5;for(let x=736;x<920;x+=18){ctx.beginPath();ctx.moveTo(x,458);ctx.lineTo(x,492);ctx.stroke();}ctx.strokeStyle='#f5f1df';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(730,458);ctx.lineTo(928,458);ctx.stroke();let o=this.orders[Math.min(this.order,2)],pt=this.carry?o.dest:o.depot;ctx.save();ctx.strokeStyle=this.carry?o.color:'#247B5A';ctx.lineWidth=3;ctx.globalAlpha=.48;ctx.setLineDash([8,9]);ctx.lineDashOffset=-game.time*35;ctx.beginPath();ctx.moveTo(this.x,this.y);ctx.lineTo(pt[0],pt[1]);ctx.stroke();ctx.restore();this.marker(ctx,pt,o.color,this.carry?o.name:'PARCEL DEPOT',!this.carry);for(const r of this.rings){ctx.globalAlpha=r.life;ctx.strokeStyle=r.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}ctx.save();ctx.translate(this.x,this.y);let ang=Math.atan2(this.vy,this.vx);if(Math.hypot(this.vx,this.vy)<5)ang=0;ctx.rotate(ang);ctx.fillStyle='rgba(20,50,60,.22)';ctx.beginPath();ctx.ellipse(2,10,23,9,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.fillStyle=C.coral;GF.Draw.roundRect(ctx,-18,-10,35,19,9,C.coral);ctx.strokeRect(-16,-8,31,15);ctx.fillStyle=C.ink;ctx.beginPath();ctx.arc(-12,12,6,0,Math.PI*2);ctx.arc(12,12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle=C.cream;ctx.fillRect(5,-6,13,8);if(this.carry){ctx.fillStyle=o.color;ctx.fillRect(-3,-23,15,13);ctx.strokeStyle=C.ink;ctx.lineWidth=2;ctx.strokeRect(-3,-23,15,13);}ctx.restore();GF.Draw.roundRect(ctx,16,14,172,48,12,'rgba(23,68,90,.91)');GF.Draw.text(ctx,'TIME  '+Math.ceil(this.timer)+'s',28,38,{size:23,color:this.timer<=10?C.coral:C.cream,align:'left'});GF.Draw.roundRect(ctx,205,70,310,43,11,'rgba(255,249,232,.94)');GF.Draw.text(ctx,this.carry?'DELIVER TO: '+o.name:'PICK UP: Parcel Depot',220,92,{size:17,color:C.ink,align:'left'});GF.Draw.roundRect(ctx,625,14,145,48,12,'rgba(23,68,90,.91)');GF.Draw.text(ctx,'DELIVERED',697,29,{size:12,color:'#bde6df'});GF.Draw.text(ctx,this.order+' / 3',697,48,{size:20,color:C.cream});GF.Draw.roundRect(ctx,786,14,158,48,12,'rgba(23,68,90,.91)');GF.Draw.text(ctx,'SCORE',800,29,{size:12,color:'#bde6df',align:'left'});GF.Draw.text(ctx,String(game.score),800,49,{size:21,color:C.sand,align:'left'});GF.Draw.text(ctx,'WASD / ARROWS • Follow the ribbon',480,522,{size:14,color:C.ink,weight:'800'});GF.Draw.vignette(ctx,960,540,.14);}
};
game.add('play',scene);game.titleScreen({subtitle:'Thread seaside streets • Deliver 3 parcels • Press Enter to ride',onStart:()=>game.go('play')});
